/** Read one CSCD search/pagination response generated by an authenticated normal browser action. */
const METHODS=['Network.responseReceived','Network.loadingFinished','Network.loadingFailed'];
const HOST='webofscience.clarivate.cn';
const PATH='/api/wosnx/core/runQueryGetRecordsStream';
const SAFE_FIELDS=['docid','colluid','ut','titles','names','identifiers','pub_info','doctypes'];

export function parseCscdResponse(raw,query,pageTitle,limit=5,displayQuery=query){
 if(typeof query!=='string'||!query.trim()||query.length>120||typeof pageTitle!=='string'||typeof displayQuery!=='string'||!displayQuery.trim()||displayQuery.length>120||!Number.isInteger(limit)||limit<1||limit>10)throw Error('检索词、页面标题或限制无效');
 const q=query.trim(),title=pageTitle.replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069]/g,'');
 if(!title.toLowerCase().includes(displayQuery.trim().toLowerCase())||!title.includes('CSCD')||!/(?:\(Topic\)|（Topic）|\(主题\)|（主题）|\(专题\)|（专题）)/i.test(title))throw Error('页面标题未确认对应 CSCD 主题检索');
 const bodies=Array.isArray(raw)?raw:[raw];if(!bodies.length||bodies.length>10)throw Error('响应数量异常');
 let info=null;const records=new Map();let haveRecords=false;
 for(const part of bodies){
  if(!part||typeof part.body!=='string'||part.body.length>16000000)throw Error('响应缺失或超限');
  let text;if(part.base64Encoded){if(!/^[A-Za-z0-9+/]*={0,2}$/.test(part.body))throw Error('响应编码异常');text=Buffer.from(part.body,'base64').toString('utf8')}else text=part.body;
  for(const line of text.split(/\r?\n/).filter(x=>x.trim())){let row;try{row=JSON.parse(line)}catch{throw Error('流式响应格式异常')}
   if(row.key==='searchInfo'){
    if(!row.payload||typeof row.payload!=='object')throw Error('搜索信息异常');
    if(info&&(String(info.RecordsFound)!==String(row.payload.RecordsFound)||String(info.RecordsAvailable)!==String(row.payload.RecordsAvailable)||String(info.QueryID)!==String(row.payload.QueryID)))throw Error('多个搜索信息不一致');
    info=row.payload;
   }
   if(row.key==='records'){
    if(!row.payload||typeof row.payload!=='object'||Array.isArray(row.payload))throw Error('记录块格式异常');haveRecords=true;
    for(const [key,x] of Object.entries(row.payload)){
     if(!/^\d+$/.test(key))throw Error('记录序号格式异常');
     if(!x||typeof x!=='object'||Array.isArray(x)||typeof x.colluid!=='string'||!/^CSCD/i.test(x.colluid))throw Error('上游记录不属于 CSCD');
     if(records.has(key)){const old=records.get(key);if(old.colluid!==x.colluid||old.ut!==x.ut||old.docid!==x.docid)throw Error('重复记录序号不一致')}else records.set(key,x);
    }
   }
  }
 }
 if(!info||!haveRecords)throw Error('缺少搜索信息或记录');
 const int=(x)=>typeof x==='number'&&Number.isSafeInteger(x)&&x>=0?x:typeof x==='string'&&/^\d+$/.test(x)&&Number.isSafeInteger(Number(x))?Number(x):null;
 const total=int(info.RecordsFound),available=int(info.RecordsAvailable);if(total===null||available===null)throw Error('总数格式异常');
 const selected=[];for(const key of [...records.keys()].sort((a,b)=>Number(a)-Number(b))){if(selected.length>=limit)break;const x=records.get(key);let clean={rank:Number(key)};for(const f of SAFE_FIELDS)if(Object.hasOwn(x,f))clean[f]=x[f];selected.push(clean)}
 return {source:'CSCD via Web of Science institutional session',query:q,display_query:displayQuery.trim(),total_found:total,total_available:available,items:selected,note:'同次页面操作后捕获并合并的流式响应；显示查询词如经翻译，须由调用方确认与输入查询词的对应关系。仅白名单题录字段，不输出 QueryID、摘要或全文。若学校合同限制自动访问或第三方 AI 处理，应先取得适用授权。当前只验证捕获的页面，不代表正式 API、全部检索模式或全文。'};
}

export async function cscdSearchResponse(tab,query,submitSearch,limit=5,displayQuery=query){
 if(typeof submitSearch!=='function')throw Error('需要由调用者提供正常提交检索或翻页的回调');
 const c=await tab.capabilities.get('cdp');await c.send('Network.enable');let cursor=(await c.readEvents({methods:METHODS})).cursor;
 await submitSearch();let ids=new Set(),finished=new Set(),failed=new Set(),bodies=new Map(),candidate=null;
 let lastRelevant=Date.now(),deadline=Date.now()+25000;
 while(Date.now()<deadline){
  const e=await c.readEvents({methods:METHODS,afterSequence:cursor,timeoutMs:candidate?1500:3000,limit:1000});cursor=e.cursor;if(e.truncated)throw Error('浏览器网络事件不完整');
  for(const event of e.events){const p=event.params||{};if(event.method==='Network.responseReceived'&&p.response?.status===200){let u;try{u=new URL(p.response.url)}catch{}if(u?.hostname===HOST&&u.pathname===PATH){ids.add(p.requestId);lastRelevant=Date.now()}}
   if(event.method==='Network.loadingFinished'){finished.add(p.requestId);if(ids.has(p.requestId))lastRelevant=Date.now()}if(event.method==='Network.loadingFailed')failed.add(p.requestId)}
  for(const id of ids){if(failed.has(id))throw Error('CSCD 检索请求失败');if(finished.has(id)&&!bodies.has(id))bodies.set(id,await c.send('Network.getResponseBody',{requestId:id}))}
  if(bodies.size){
   const u=new URL(await tab.url());if(u.hostname!==HOST||!u.pathname.startsWith('/wos/cscd/summary/'))continue;
   const label=await tab.playwright.evaluate(()=>document.querySelector('button[data-ta="search-terms"]')?.innerText?.trim()||'');
   const title=label?label+' CSCD':await tab.title();try{candidate=parseCscdResponse([...bodies.values()],query,title,limit,displayQuery)}catch(err){if(!['缺少搜索信息或记录','页面标题未确认对应 CSCD 主题检索'].includes(err.message))throw err}
  }
  if(candidate&&Date.now()-lastRelevant>=1200&&[...ids].every(id=>finished.has(id))){
   if(!candidate.items.length)throw Error('暂无可与页面核对的 CSCD 记录');
   await tab.playwright.locator('a[href*="/wos/cscd/full-record/CSCD:"]').first().waitFor({state:'visible',timeoutMs:10000});
   const idsOnPage=await tab.playwright.evaluate(()=>[...document.querySelectorAll('a[href*="/wos/cscd/full-record/CSCD:"]')].map(a=>(a.getAttribute('href')||'').split('/').pop().split('?')[0].split('#')[0]).filter(x=>/^CSCD:[A-Za-z0-9._-]+$/.test(x)));
   if(candidate.items.some(x=>typeof x.ut!=='string'||!idsOnPage.includes(x.ut)))throw Error('页面记录标识与响应不一致');
   return candidate;
  }
  await new Promise(resolve=>setTimeout(resolve,250));
 }
 throw Error('未收到完整 CSCD 同次搜索响应；请检查会话和页面');
}
